type Schema = Record<string, any>;

function resolve(ref: string): Schema {
  let value: any = APP_SHELL_SCHEMA;
  for (const part of ref.replace(/^#\//, "").split("/")) value = value[part];
  return value;
}

function check(schema: Schema, value: unknown): void {
  if (schema.$ref) return check(resolve(schema.$ref), value);
  if ("const" in schema && !Object.is(value, schema.const))
    throw new Error("constant mismatch");
  if (
    Array.isArray(schema.enum) &&
    !schema.enum.some((entry: unknown) => Object.is(entry, value))
  )
    throw new Error("enum mismatch");
  for (const key of ["anyOf", "oneOf"] as const) {
    if (!Array.isArray(schema[key])) continue;
    let passed = 0;
    for (const candidate of schema[key]) {
      try {
        check(candidate, value);
        passed++;
      } catch (error) {
        if (!(error instanceof Error)) throw error;
      }
    }
    if (key === "anyOf" ? passed < 1 : passed !== 1)
      throw new Error(`${key} mismatch`);
  }
  if (Array.isArray(schema.allOf))
    for (const candidate of schema.allOf) check(candidate, value);
  if (schema.type === "object") {
    if (typeof value !== "object" || value === null || Array.isArray(value))
      throw new Error("object expected");
    const item = value as Record<string, unknown>;
    for (const required of schema.required ?? [])
      if (!(required in item)) throw new Error("missing field");
    const properties = schema.properties ?? {};
    if (schema.additionalProperties === false)
      for (const key of Object.keys(item))
        if (!(key in properties)) throw new Error(`unknown field ${key}`);
    for (const [key, property] of Object.entries(properties))
      if (key in item) check(property as Schema, item[key]);
  }
  if (schema.type === "array") {
    if (!Array.isArray(value)) throw new Error("array expected");
    if (schema.minItems !== undefined && value.length < schema.minItems)
      throw new Error("array too short");
    if (schema.maxItems !== undefined && value.length > schema.maxItems)
      throw new Error("array too long");
    if (
      schema.uniqueItems &&
      new Set(value.map((item) => JSON.stringify(item))).size !== value.length
    )
      throw new Error("duplicate array item");
    if (schema.items) for (const item of value) check(schema.items, item);
  }
  if (schema.type === "string") {
    if (typeof value !== "string") throw new Error("string expected");
    if (schema.minLength !== undefined && [...value].length < schema.minLength)
      throw new Error("string too short");
    if (schema.maxLength !== undefined && [...value].length > schema.maxLength)
      throw new Error("string too long");
    if (schema.pattern && !new RegExp(schema.pattern).test(value))
      throw new Error("pattern mismatch");
  }
  if (schema.type === "integer") {
    if (typeof value !== "number" || !Number.isSafeInteger(value))
      throw new Error("safe integer expected");
    if (schema.minimum !== undefined && value < schema.minimum)
      throw new Error("number too small");
    if (schema.maximum !== undefined && value > schema.maximum)
      throw new Error("number too large");
  }
  if (schema.type === "number") {
    if (typeof value !== "number" || !Number.isFinite(value))
      throw new Error("finite number expected");
    if (schema.minimum !== undefined && value < schema.minimum)
      throw new Error("number too small");
    if (schema.maximum !== undefined && value > schema.maximum)
      throw new Error("number too large");
  }
  if (schema.type === "boolean" && typeof value !== "boolean")
    throw new Error("boolean expected");
}

function freeze<T>(value: T): T {
  if (value && typeof value === "object" && !Object.isFrozen(value)) {
    Object.freeze(value);
    for (const child of Object.values(value as Record<string, unknown>))
      freeze(child);
  }
  return value;
}

export function parseAppAppearance(value: unknown): AppAppearance {
  check({ $ref: "#/$defs/AppAppearanceWire" }, value);
  return freeze(value as AppAppearance);
}
export function parseAppSnapshot(value: unknown): AppSnapshot {
  check({ $ref: "#/$defs/AppSnapshotWire" }, value);
  return freeze(value as AppSnapshot);
}
export function parseAppIntent(value: unknown): AppIntent {
  check({ $ref: "#/$defs/AppIntentWire" }, value);
  return freeze(value as AppIntent);
}
export function parseAppOutcome(value: unknown): AppOutcome {
  check({ $ref: "#/$defs/AppOutcomeWire" }, value);
  return freeze(value as AppOutcome);
}
export function parseAppError(value: unknown): AppError {
  check({ $ref: "#/$defs/AppErrorWire" }, value);
  return freeze(value as AppError);
}
export function parseAppEventCursor(value: unknown): AppEventCursor {
  check({ $ref: "#/$defs/ReplayWire" }, value);
  return freeze(value as AppEventCursor);
}
export function validateAppShell(value: unknown): void {
  const errors: unknown[] = [];
  for (const candidate of APP_SHELL_SCHEMA.oneOf as readonly Schema[]) {
    try {
      check(candidate, value);
      return;
    } catch (error) {
      errors.push(error);
    }
  }
  throw new Error(
    `invalid App Shell value (${errors.length} alternatives rejected)`,
  );
}
